// Generated by Oriel from the [Service] classes of BackOffice. Do not edit.
/* eslint-disable */

class CallErrorBase extends Error {
  /** The method that failed, as "Service.Method". */
  readonly method: string;
  /** The code of a [ServiceError] exception, or null. */
  readonly code: string | null;
  /** The public properties of a [ServiceError] exception, or null. */
  readonly data: unknown;

  constructor(method: string, message: string, code: string | null = null, data: unknown = null) {
    super(message);
    this.name = "CallError";
    this.method = method;
    this.code = code;
    this.data = code === null ? null : data;
  }
}

/**
 * The error a call rejects with: the C# method threw, or its arguments did not fit its parameters.
 * Errors of [ServiceError] exceptions have their code, which tells their data's type.
 */
export type CallError = CallErrorBase & ({ readonly code: "invalid"; readonly data: InvalidCustomerException } | { readonly code: "not-found"; readonly data: CustomerNotFoundException } | { readonly code: null; readonly data: null });
// One class for the clients of every assembly, so that instanceof CallError holds whichever threw.
const callErrors = globalThis as { [key: symbol]: unknown };
const SharedCallError = (callErrors[Symbol.for("oriel.CallError")] ??= CallErrorBase) as typeof CallErrorBase;
export const CallError = SharedCallError as unknown as {
  new (method: string, message: string, code?: string | null, data?: unknown): CallError;
  readonly prototype: CallError;
};

interface Bridge {
  call(method: string, args: unknown[]): Promise<unknown>;
  on(event: string, listener: (payload: unknown) => void): () => void;
}

function bridge(): Bridge {
  const runtime = (globalThis as { oriel?: Bridge }).oriel;
  if (!runtime) throw new Error("Oriel: window.oriel is missing; open this page in an Oriel window");
  return runtime;
}

async function call<T>(method: string, ...args: unknown[]): Promise<T> {
  // Arguments left out stay out, so that C# uses its defaults.
  while (args.length > 0 && args[args.length - 1] === undefined) args.pop();
  try {
    return (await bridge().call(method, args)) as T;
  } catch (err) {
    if (err instanceof Error && err.name === "CallError") {
      const { code, data } = err as { code?: string | null; data?: unknown };
      throw new CallError(method, err.message, code ?? null, data);
    }
    throw err;
  }
}

function on<T>(event: string, listener: (payload: T) => void): () => void {
  return bridge().on(event, listener as (payload: unknown) => void);
}

// ---- Types ----

/** A customer of the back office. Id 0 is one not saved yet. */
export interface Customer {
  id: number;
  name: string;
  email: string;
  tier: Tier;
  balance: number;
  joined: string;
}

/** A customer that is gone, deleted by another window. */
export interface CustomerNotFoundException {
  readonly id: number;
}

/** Some rows of the customers that match, and how many match in all. */
export interface CustomerPage {
  total: number;
  rows: Customer[];
}

/** A customer that cannot be saved as it is: what is wrong, by field. */
export interface InvalidCustomerException {
  /** What is wrong with each field, by its name in the page: `email`. */
  readonly errors: Record<string, string>;
}

/** The columns customers sort by. */
export type SortBy = "id" | "name" | "email" | "tier" | "balance" | "joined";

/** What a customer pays for. */
export type Tier = "free" | "pro" | "enterprise";

// ---- Services ----

/** The customers: pages of them for the grid, and saving one from the form. */
export const Customers = {
  /** The customers from offset, limit of them at most, whose name or email has search. */
  page(offset: number, limit: number, search?: string | null, sort?: SortBy, descending?: boolean): Promise<CustomerPage> {
    return call("Customers.Page", offset, limit, search, sort, descending);
  },
  /** Saves customer: a new one when its id is 0. Returns it as saved. */
  save(customer: Customer): Promise<Customer> {
    return call("Customers.Save", customer);
  },
  /** Deletes the customer id. */
  delete(id: number): Promise<void> {
    return call("Customers.Delete", id);
  },
  /**
   * Fires with a customer saved, so that every window shows it.
   * Calls listener with each payload of Customers.Saved; returns a function that stops listening.
   */
  onSaved(listener: (payload: Customer) => void): () => void {
    return on<Customer>("Customers.Saved", listener);
  },
  /**
   * Fires with the id of a customer deleted.
   * Calls listener with each payload of Customers.Deleted; returns a function that stops listening.
   */
  onDeleted(listener: (payload: number) => void): () => void {
    return on<number>("Customers.Deleted", listener);
  },
} as const;

// ---- Window ----

/**
 * Fires when files are dropped on this window, with their full paths and where they were
 * dropped, in CSS pixels of the page; the page's own drop event has their File objects.
 * Returns a function that stops listening.
 */
export function onFilesDropped(listener: (drop: { paths: string[]; x: number; y: number }) => void): () => void {
  return bridge().on("oriel:filesDropped", listener as (payload: unknown) => void);
}
